(function(){"use strict";document.addEventListener("DOMContentLoaded",function(){var n=document.querySelectorAll(".alert-auto");n.forEach(function(n){setTimeout(function(){window.bootstrap&&bootstrap.Alert?bootstrap.Alert.getOrCreateInstance(n).close():n.style.display="none"},4e3)})});document.addEventListener("DOMContentLoaded",function(){var n=document.querySelectorAll(".tag-filter .btn");n.forEach(function(t){t.addEventListener("click",function(){n.forEach(function(n){n.classList.remove("active","btn-primary");n.classList.add("btn-outline-secondary")});t.classList.remove("btn-outline-secondary");t.classList.add("active","btn-primary")})})})})();